//! Compare original provider/dispatch join with eight retained controlled rows.
use spore_core::{cell_camera_component_provider_v1::project,cell_camera_actor_branch_v1::Slot};
fn w(b:&[u8],o:usize)->u32{u32::from_le_bytes(b[o..o+4].try_into().unwrap())}
fn main(){let mut a=std::env::args().skip(1);let b=std::fs::read(a.next().expect("native stdout")).unwrap();let map=std::fs::read_to_string(a.next().expect("host map")).unwrap();assert_eq!(b.len(),480);
 let lines:Vec<_>=map.lines().filter(|l|l.split_whitespace().nth(1)==Some("Target")).collect();assert_eq!(lines.len(),1);let target=u32::from_str_radix(lines[0].split_whitespace().nth(2).unwrap(),16).unwrap();
 let sb=[10f32.to_bits(),20f32.to_bits(),30f32.to_bits()];let sc=[3f32.to_bits(),4f32.to_bits(),5f32.to_bits()];let player=[2f32.to_bits(),4f32.to_bits()];let slots=[Slot{handle:0x10000,position:[5f32.to_bits(),8f32.to_bits(),11f32.to_bits()]}];let mut aggregate=[0u8;24];aggregate[..4].copy_from_slice(&1u32.to_le_bytes());aggregate[4..8].copy_from_slice(&0x98c942b2u32.to_le_bytes());aggregate[12..16].copy_from_slice(&1f32.to_bits().to_le_bytes());aggregate[20..24].copy_from_slice(&2f32.to_bits().to_le_bytes());
 for (i,a) in [0f32,0.5,0.75,1.,0.75,0.75,0.75,0.75].into_iter().enumerate(){let state=match i{3=>0x30,5=>7,_=>0x29};let component=match i{2=>0,7=>0x20000,_=>0x10000};let fc=if i==6{0}else{1};let x=project(sb,sc,a.to_bits(),if i==0{None}else{Some(player)},0,component,fc,&[true],state,&aggregate,if i==4{0x20000}else{0x10000},0,&slots,0x027f,0x1f80,true).unwrap();let d=x.dispatch;let o=i*60;
  for j in 0..3{assert_eq!(w(&b,o+4*j),d.b[j],"B {i}/{j}");assert_eq!(w(&b,o+12+4*j),d.earlier.c[j],"C {i}/{j}");}assert_eq!(w(&b,o+24),d.earlier.ramp_or_alpha);let fp=w(&b,o+28);assert_eq!(fp&0xffff,0x027f);assert_eq!((fp>>16)&0x3840,0);assert_eq!(w(&b,o+32)&!0x3f,0x1f80);assert_eq!(w(&b,o+36),a.to_bits());assert_eq!(w(&b,o+40),0xc0dec0de);assert_eq!(w(&b,o+44),0xa5a5a5a5);assert_eq!(w(&b,o+48),u32::from(d.provider_called));assert_eq!(w(&b,o+52),if d.resolved_index.is_some(){target}else{0});assert_eq!(w(&b,o+56),d.scalar.unwrap_or(0xa5a5a5a5));
 }println!("matched eight controlled component-provider rows; unchecked alias and synthetic pools admitted");}
